const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definitions
  const lakeLangano = ee.Geometry.Polygon([[
    [38.65, 7.60], [38.65, 7.50], [38.85, 7.50], [38.85, 7.60], [38.65, 7.60]
  ]]);

  const lakeAbijata = ee.Geometry.Polygon([[
    [38.55, 7.65], [38.55, 7.55], [38.75, 7.55], [38.75, 7.65], [38.55, 7.65]
  ]]);

  // 2. Data Acquisition
  const s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate('2022-03-29', '2022-03-30')
    .filterBounds(ee.Geometry.MultiPolygon([lakeLangano, lakeAbijata]));

  const colSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 images on 2022-03-29: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get least cloudy image and calculate NDTI
  const image = s2Col.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Calculate Normalized Difference Turbidity Index (Red - Green)/(Red + Green)
  const ndti = image.normalizedDifference(['B4', 'B3']).rename('NDTI');

  // 4. Extract values for both lakes
  const langanoStats = ndti.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: lakeLangano,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const abijataStats = ndti.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: lakeAbijata,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const langanoMean = langanoStats.NDTI_mean;
  const langanoCount = langanoStats.NDTI_count;
  const abijataMean = abijataStats.NDTI_mean;
  const abijataCount = abijataStats.NDTI_count;

  console.log(`Lake Langano - NDTI: ${langanoMean?.toFixed(4)}, Pixels: ${langanoCount}`);
  console.log(`Lake Abijata - NDTI: ${abijataMean?.toFixed(4)}, Pixels: ${abijataCount}`);

  // 5. Validation & Final Answer
  if (langanoCount === 0 || abijataCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (langanoMean === null || abijataMean === null || 
      isNaN(langanoMean) || isNaN(abijataMean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Higher NDTI = more turbid/brown water
  if (langanoMean > abijataMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
